            analyzer = oldAnalyzer.extend(sparams, staticenv.KindEnv.withExtendsConditions(where, List(tw)))
          walk(tw); analyzer = inDecl }
        walk(params); walk(decls); walk(self)
        analyzer = oldAnalyzer

